import{_ as o,l as t,o as a,c as r,v as l,p as d,x as n,d as s,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Mundell 1963 资本流动","description":"","frontmatter":{"title":"Mundell 1963 资本流动","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mundell-1963-paper.md","filePath":"econ/mundell-1963-paper.md","lastUpdated":1789023840000}'),c={name:"econ/mundell-1963-paper.md"};function m(u,e,h,B,A,P){const i=t("Mermaid");return a(),r("div",null,[e[1]||(e[1]=l('<h1 id="mundell-1963-资本流动" tabindex="-1">Mundell 1963 资本流动 <a class="header-anchor" href="#mundell-1963-资本流动" aria-label="Permalink to &quot;Mundell 1963 资本流动&quot;">​</a></h1><div class="epigraph"><p>资本高度流动时，固定汇率下货币政策让给汇率锚，财政政策对产出更有效；浮动则相反。</p><footer>—— Mundell, Capital Mobility and Stabilization Policy under Fixed and Flexible Exchange Rates, Canadian Journal of Economics and Political Science 1963</footer></div><p>附录对照，不插入主干。<a href="/econ/lucas-1976-paper">上一课</a>对照的是政策评价不能用简化式。本篇对照 <strong>Mundell 1963 原文的问题设定</strong>：稳定化工具在开放经济里如何随资本流动与汇率制度换位。主干<a href="/econ/mundell-fleming">蒙代尔–弗莱明</a>已取 IS–LM 加 \\(NX\\) 与完全流动极限；这里对照 <em>CJEPS</em> 短文如何把资本流动写成改变指派的关键参数，以及 Fleming（1962）为何是并列的 IMF 文本而不是本章定理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>封闭 IS–LM 里，财政与货币都对 \\(Y\\) 有杠杆，分工靠斜率。开放后，资本随利率差流动，汇率制度决定 \\(M\\) 是否还能当工具。Mundell 问的缺口是：在价格粘住的短局里，<strong>完全资本流动</strong>如何把有效工具换成制度的函数——钉住则货币内生，浮动则财政被升值挤出。这不是长期 PPP，也不是外汇微观结构。</p><p>稍早的指派文还允许不完全流动，内部与外部平衡可以各派一种工具。1963 年把流动推到极限，钉住下货币完全失去稳定产出的独立性，浮动下财政的产出效应被汇率吃掉。极限是为了把分叉画死，不是声称 1963 年的资本已经完美流动。</p><p>原文用流量 IS、静态预期、\\(i=i^*\\) 的极限。未抛补利率平价带预期贬值、粘性价格下的超调，是后文；1963 年先把制度分叉画清楚。指派问题（内部与外部平衡各用哪一种工具）在 Mundell 稍早的文章里已经出现；本篇把资本流动推到极限，分叉变得最锋利。</p><p><span class="marginnote">Mundell, <em>Canadian Journal of Economics and Political Science</em> 29(4), 1963, 475–485。期刊后来拆成 <em>CJE</em>。Fleming, <em>IMF Staff Papers</em> 1962 是并列装置，不要把两人写成互为引理，也不要发明 arXiv。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>IS 加净出口，LM 或利率，BP 由资本流动与经常账户。完全流动、静态预期、固定 \\(E\\)：任何想把 \\(i\\) 打下 \\(i^*\\) 的货币扩张被储备流失冲掉，\\(M\\) 缩回；财政抬 \\(Y\\) 与货币需求，为维持 \\(E\\)，央行被动扩 \\(M\\)。浮动：\\(M\\) 可独立，货币扩张贬值并抬 \\(Y\\)；财政推高 \\(i\\)、\\(E\\) 升值，\\(NX\\) 挤出。</p>',10)),(a(),d(E,null,{default:n(()=>[p(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20MOB%5B%22%E8%B5%84%E6%9C%AC%E9%AB%98%E5%BA%A6%E6%B5%81%E5%8A%A8%22%5D%20--%3E%20REG%5B%22%E6%B1%87%E7%8E%87%E5%88%B6%E5%BA%A6%E5%88%86%E5%8F%89%22%5D%0A%20%20FIX%5B%22%E5%9B%BA%E5%AE%9A%20E%22%5D%20--%3E%20FIS%5B%22%E8%B4%A2%E6%94%BF%E7%9B%B8%E5%AF%B9%E6%9C%89%E6%95%88%2C%20%E8%B4%A7%E5%B8%81%E5%86%85%E7%94%9F%22%5D%0A%20%20FLT%5B%22%E6%B5%AE%E5%8A%A8%20E%22%5D%20--%3E%20MON%5B%22%E8%B4%A7%E5%B8%81%E7%9B%B8%E5%AF%B9%E6%9C%89%E6%95%88%2C%20%E8%B4%A2%E6%94%BF%E8%A2%AB%E6%8C%A4%E5%87%BA%22%5D%0A%20%20REG%20--%3E%20FIX%0A%20%20REG%20--%3E%20FLT%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<p>主干课已写长期 PPP 拉回与中性；附录不重做比较静态图，只对照 1963 年的靶子是稳定化指派，不是估算贸易弹性。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是储备或汇率承担调整。钉住加流动：利率被国外钉住，货币供给变成内生余量，财政「有效」其实是货币被迫配合。浮动：汇率承担支出转换，货币经贬值强化，财政经升值削弱。\\(CA=S-I\\) 事后仍是恒等；BP 是事前外部相容，不是对恒等的否定。</p><p>静态预期下 \\(i=i^*\\) 是无抛补的退化：预期贬值为零。一旦钉住不可信，资本流出可以在储备耗尽前就把 \\(i\\) 打离 \\(i^*\\)——原文不写危机，极限命题假定锚被相信。主干课已点 Dornbusch 超调作动态补丁；附录不把 1963 年改写成超调模型。</p><h3 id="对照主干-mf-课-不插入批判与三角之间" tabindex="-1">对照主干 MF 课，不插入批判与三角之间 <a class="header-anchor" href="#对照主干-mf-课-不插入批判与三角之间" aria-label="Permalink to &quot;对照主干 MF 课，不插入批判与三角之间&quot;">​</a></h3><p>主干<a href="/econ/mundell-fleming">蒙代尔–弗莱明</a>已从 PPP 短局接到制度分叉，下一课才是不可能三角。本附录对照 1963 年把资本流动推到极限的那一刀，以及静态预期、\\(i=i^*\\) 的教学版。把 <em>CJEPS</em> 接在 Lucas 原文之后只因为附录链如此排，<strong>不插入</strong>宏观主干，也不把外汇订单簿写进来。读完回主干 MF 课。</p><p><span class="marginnote">完美流动极限：浮动时财政可被升值完全挤出。不完全流动介于两极端。CIP 的掉期会计在量化栏利率平价，本课的 \\(i=i^*\\) 不是报价。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 1963 写成已经包含风险溢价、大国 \\(i^*\\) 内生、或新凯恩斯开放经济的欧拉。Dornbusch 超调是理性预期加粘性 \\(P\\) 的动态补丁。资本管制拿掉完全流动，分叉改变——正是主干三角课。也不要把 MF 写成对限价簿外汇订单的描述。</p><p>福利排序不在这篇：浮动的实际汇率波动与钉住的输入通胀要另评。原文是稳定化有效性，不是最优货币区的完整清单（最优货币区是 Mundell 另一篇）。</p><p>宏观与货币的论文对照链到此结束。不要把三篇增长–批判–开放原文当成插入主干的连续单元。</p><p>静态预期下钉住若不可信，\\(i\\) 可以暂时离开 \\(i^*\\)，储备仍有限。原文取可信钉住与完全流动，为的是极限命题干净。</p><p>不可能三角把「资本流动、固定汇率、独立货币」收成三选二，是主干后课对这篇极限的收口。1963 年先把其中两角钉死，看第三角如何让渡。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Mundell 1963：资本流动使稳定化工具随汇率制度换位。</li><li>钉住则货币让给锚，浮动则财政被汇率挤出。</li><li>Fleming 1962 并列；UIP/CIP 市场内容与外汇微观结构不在此重写。</li><li>出处：Mundell, <em>CJEPS</em> 1963。</li></ul>',15))])}const M=o(c,[["render",m]]);export{f as __pageData,M as default};
